else:
    def has_single_arg(func):
        """Check if function has exactly one positional arg and optional keyword-only args."""
        spec = inspect.signature(func)
        params = list(spec.parameters.values())
        if not params:
            return False
        # Check first param is positional (not VAR_POSITIONAL/VAR_KEYWORD)
        first = params[0]
        if first.kind in (inspect.Parameter.VAR_POSITIONAL, inspect.Parameter.VAR_KEYWORD):
            return False
        # Check remaining params are keyword-only with defaults
        for p in params[1:]:
            if p.kind == inspect.Parameter.KEYWORD_ONLY:
                if p.default is inspect.Parameter.empty:
                    return False  # Required kwonly arg
            elif p.kind in (inspect.Parameter.POSITIONAL_OR_KEYWORD, inspect.Parameter.POSITIONAL_ONLY):
                return False  # Additional positional arg
            else:
                return False  # VAR_* parameter
        return True

